SET EMAIL_NOTIFY_ENABLED = #{emailNotifyEnabled},
    DISASTER_NOTIFY_ENABLED = #{disasterNotifyEnabled},
    REPORT_NOTIFY_ENABLED = #{reportNotifyEnabled}
WHERE MEMBER_ID = #{memberId}
